  [10021] = {
    [1] = {
      uid = 22,
      next = 2,
      beijing = 1422,
      sentence = "第一次认识到自己的无力是那次逃跑失败。\n第二次是母亲逝世时的无所适从。\n第三次则是面对茫茫人海时的无计可施。\n  \n\n李泽言不会说自己持续不断地找了女孩十七年——\n就像人们谈起暗恋的时候一样：虽然嘴上总说着“我暗恋了TA多少多少年”、“这么些年来始终关注着TA”，但到头来该做的事依旧半点都没耽搁。\n\n“寻找女孩”之于李泽言，也是这样一个概念。",
      music = "05_Dream",
