    [7] = {
      uid = 77,
      next = 0,
      beijing = 1221,
      sentence = "不过这个问题的答案他魏谦是永远都不可能有胆子向李泽言求证了。\n\n尤其是随着华锐越做越好名声越来越响，他魏谦本来就算不上大的胆子也成比例地缩小了。",
      music = "04_Normal",
