    [3] = {
      uid = 3879,
      next = 4,
      beijing = 4966,
      sentence = "毕竟从他的视角看，这局游戏里“开发商”确实并不止是想获得这个楼盘，但具体的原因，他也还没猜得出来。\n\n越是去想，这件原本不值得在意的事却越让毕胜较劲起来。\n\n“对了锋哥，我还有件事想问你。”\n\n“什么事你说。”\n\n“我不是也在做个人任务吗？主要就是帮开发商跑跑腿，放放信件什么的。”",
      music = "19_Daily02",
      voice = "est_12174_3.mp3"
