  },
  [20011] = {
    [1] = {
      uid = 207,
      next = 2,
      beijing = 1521,
      sentence = "大家都知道，小区里有个特别聪明的孩子。\n  \n他的父母都是高级科研人员，虽然夫妇二人一直为人低调，但坊间还是流出了不少关于他们孩子的传说——1岁认字上万、3岁读通《时间简史》、5岁就已经跟着爸妈搞科研。\n\n其中多少是真是假，邻居们并不作深究。他们只是需要一个“别人家的孩子”做范本，在教育自家孩子时增加点说服力，“小祖宗，你还能不能让我省点心了！你看看隔壁家的小天才，5岁就懂得乖乖在家看书了！”",
      music = "19_Daily02",
      voice = "est_20011_1.mp3"
