    [7] = {
      uid = 4301,
      next = 0,
      beijing = 1301,
      sentence = "紧握着手中连讣告都算不上的文档，他似乎神游到了那个意气风发的午后。他们共同站在学校的最高处，大声诉说着彼此共同的理想，喊给整个世界听。\n\n“我们一起让世界变得更好。”",
      music = "88_Idealcity",
