  [30011] = {
    [1] = {
      uid = 429,
      next = 2,
      beijing = 1941,
      sentence = "夜凉如水，月光透过小而窄的窗户洒了进来，照亮了窗边的半个床铺和床上男孩熟睡的脸庞。\n\n男孩年纪很小，穿着麻布睡衣抱着破旧的玩具熊，小小的一团蜷缩在床上。\n\n他睡得很不安稳，小手紧张兮兮地抓住被角微微挣扎，手臂上隐约露出了一段青紫，睫毛湿漉漉的，不知道梦见了什么。",
      music = "11_Sorrow_LongEnding_Ver",
      voice = "est_30011_1.mp3"
