  [30013] = {
    [1] = {
      uid = 439,
      next = 2,
      beijing = 1931,
      sentence = "1562知道院长说的不是真话。\n\n他们每个星期都会接受福利院的药物注射，有些孩子注射后一切如常；有些孩子却会身体逐渐虚弱，直到死掉；有些孩子会失去理智，开始发疯；\n\n而有些孩子则会开始拥有不可控的力量，比如刚刚那个一边尖叫一边引起了爆炸的孩子。",
      music = "11_Sorrow_LongEnding_Ver",
