  [40021] = {
    [1] = {
      uid = 679,
      next = 2,
      beijing = 1233,
      sentence = "“没问题，就交给我吧白哥！”韩野叠起了沾满血迹的信封，口气里是被委以重任的认真，转而又变成了担心，“不过白哥，你真的不要去趟医院吗？”\n  \n那个被叫做“白哥”的少年在他说话间，已经将身体重新归置到阴影处。\n  \n他淡淡地摇摇头，脸上满是乌青和伤口，下巴处还有未干的血迹。他瞥了韩野一眼一字一句说得很清晰：\n\n“你帮我重新抄一份，别吓到她。”",
      music = "07_Romantic",
      voice = "est_40021_1.mp3"
    },
    [2] = {
      uid = 680,
      next = 3,
      beijing = 1233,
      sentence = "韩野板着原本就不严肃的脸应承着，不过转念一想，这样难道不更酷吗，这好比一段战火纷飞里的爱情啊！骨子里都是迸发出来的中二气息。\n  \n在夕阳已经能照进教室的黄昏，他悄悄摸到了信封上所写的女生的座位，将信封掏出来放到了女生的抽屉里。突然想起了什么似的，他翻出自己的笔，在那原本就沾满血迹的信封上，写上了大大的两个字——",
      music = "07_Romantic",
      voice = "est_40021_2.mp3"
    },
    [3] = {
      uid = 681,
      next = 0,
      beijing = 1233,
      sentence = "信被摆在抽屉最醒目的位置，仿佛等待着明天主人的检阅。\n\n但上面沾染的红色，又好比某种狰狞而温柔的心迹。\n  \n那两个字，清晰地写在信封上，看起来竟还像某种邀功的炫耀——\n\n“白起”。",
