  [40023] = {
    [1] = {
      uid = 687,
      next = 2,
      beijing = 1532,
      sentence = "白起再次遇到女孩，是三天后的黄昏。他路过图书馆时恰好遇到女孩走进去的背影，于是神使鬼差地刷开了图书馆的门禁。\n\n女孩在一个书架前皱着眉头，看着那本被摆放在老式书架最高层的书，有两米多高吧，她怎么踮脚都够不着，懊恼得差点要去搬椅子过来踩上去。\n  \n白起的手轻巧地越过她的头顶，把书递到她的手边。\n  \n那是一本染了尘埃的《拜伦诗集》，白起在心里默默记了一笔。",
      music = "07_Romantic",
      voice = "est_40023_1.mp3"
