    [2] = {
      uid = 730,
      next = 3,
      beijing = 1451,
      sentence = "厉晔没有其他想法，纯粹觉得白起是个有故事的人，不愿看他冷冰冰地远离战友独自一个人生活，特别是格斗课时还需要和战友一起练习……\n  \n其他的战友虽然也觉得白起这个人冷冰冰的不好接近，甚至也有发生各种觉得白起“太冷傲，要煞煞他威风”的挑衅事件，但不论怎么说大家都是“同一类人”，加上厉晔这么一个“和事佬”， 以及还有次因为在白起的衣物中发现了张不知是哪个女孩的照片而集体起哄。\n\n久而久之白起渐渐的也没有之前那么抗拒了，当然还是依旧没有摆什么好脸色。",
      music = "05_Dream",
      voice = "est_40043_2.mp3"
