  [40044] = {
    [1] = {
      uid = 734,
      next = 2,
      beijing = 1081,
      sentence = "话音刚落，椅子上已经没了男人的身影，刹那间，白起偏过头，抬起手稳稳地接住了从左后方攻来的拳头，另一只拳头即将向对方迎面砸去时，对方居然闪至了离他有足足两米开外的窗口。\n  \n男人哈哈大笑，鼓了鼓掌：“速度还可以。”\n  \n他可以看得出来——这个少年身上有一股子狠劲儿。他整个人看起来冷冰冰的，但更为冰冷的，是他的招式。\n  \n白起向男子敬了个军礼，迅速恢复军姿站好。",
      music = "05_Dream",
