    [3] = {
      uid = 741,
      next = 4,
      beijing = 1811,
      sentence = "钱宇看着浮于半空的少年，突然怒目圆睁，发出一声怒吼！瞬间，他的身体肌肉变得膨胀与紧实，连颜色都不同于原本，有点微微泛黑。\n\n白起双目微睁，迅速反应过来那是——\n  \n“小心！”白起大喊一声！往下俯冲的同时将离他最近的一个兄弟迅速扯过，卧倒！",
      music = "05_Dream",
