  [42173] = {
    [1] = {
      uid = 3940,
      next = 2,
      beijing = 2261,
      sentence = "又是一天过去，村里又淘汰了两名玩家，里面并没有平常。\n\n开会时还是一如既往的村民视角，话题在他身上只盘旋了半分钟后，又转移到谁是凶手上了。甚至因为他被确定为好人，大家都不用在他身上“浪费”时间了。\n\n就这样，在徐徐的声势之中，身为好人的他，再次投出了自己“毫无影响”的一票。",
      music = "04_Normal",
