    [5] = {
      uid = 3804,
      next = 6,
      beijing = 3182,
      sentence = "“这里有贴图错误，可能会被玩家看到！先随便空投个什么……不是，我这是中式地图！你给我个罗马立柱也太随便了吧？！”\n\n不时就会冒出的“求救”声让他紧绷着神经，生怕遗漏什么BUG。",
      music = "03_Daily",
